'use client';
import React, { useState } from 'react';
import AnimatedHeading from './AnimatedHeading';
import { useCurrency } from '@/context/CurrencyContext';

export interface FAQItem {
  q: string;
  a: string;
}

interface FaqSectionProps {
  faqs?: FAQItem[];
  theme?: 'light' | 'dark';
}

const defaultFaqs: FAQItem[] = [
  {
    q: "What is WeNest Real Estate LLC?",
    a: "WeNest Real Estate LLC is a UAE-based off-plan property agency founded in 2026, helping international investors from Australia, New Zealand, Hong Kong, Singapore, England, Turkey, Armenia, and beyond purchase property in Dubai and the UAE remotely."
  },
  {
    q: "What types of properties does WeNest offer?",
    a: "WeNest offers a curated selection of off-plan properties including apartments, studio apartments, villas, townhouses, duplexes, penthouses and commercial units across Dubai and the wider UAE."
  },
  {
    q: "Can I invest in UAE property from overseas without visiting Dubai?",
    a: "Yes. WeNest is built specifically for offshore investors. The entire process - from project selection to reservation and transaction - can be completed remotely without visiting a showroom or travelling to the UAE."
  },
  {
    q: "Which countries does WeNest serve?",
    a: "WeNest currently serves investors based in Australia, New Zealand, Hong Kong, Singapore, England, Turkey, and Armenia, providing a secure, 100% remote transaction path on WhatsApp."
  },
  {
    q: "What currencies does WeNest accept?",
    a: "All WeNest property listings are priced in AUD, USD and AED to provide international buyers with stable, predictable pricing."
  }
];

export default function FaqSection({ faqs = defaultFaqs, theme = 'light' }: FaqSectionProps) {
  const [openIndex, setOpenIndex] = useState<number | null>(null);
  const { convertPriceText } = useCurrency();

  const toggleFaq = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  const isLight = theme === 'light';

  const sectionBg = isLight ? '#ffffff' : '#02042d';
  const headingColor = isLight ? '#02042d' : '#ffffff';

  return (
    <section 
      style={{
        backgroundColor: sectionBg,
        padding: 'clamp(45px, 7.5vw, 117px) 16px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
      }}
    >
      <div style={{ maxWidth: '800px', width: '100%', display: 'flex', flexDirection: 'column', gap: '32px' }}>
        <AnimatedHeading
          text="Frequently Asked Questions"
          style={{
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: 'clamp(30px, 5vw, 60px)',
            letterSpacing: '-1px',
            lineHeight: '1.1em',
            color: headingColor,
            margin: '0 0 16px 0',
            textAlign: 'center'
          }}
        />

        <div className="flex flex-col gap-4">
          {(faqs && faqs.length > 0 ? faqs : defaultFaqs).map((faq, index) => {
            const isOpen = openIndex === index;
            
            // Border logic
            const borderColor = isOpen 
              ? '#e0c996' 
              : (isLight ? 'rgba(2,4,45,0.1)' : 'rgba(224,201,150,0.3)');
              
            // Question Text logic
            const questionColor = isOpen 
              ? '#02042d' 
              : (isLight ? '#02042d' : '#ffffff');
              
            // Answer Text logic
            const answerColor = isOpen 
              ? '#02042d' 
              : (isLight ? 'rgba(2,4,45,0.7)' : 'rgba(255,255,255,0.7)');

            // Toggle Icon Color
            const iconColor = isOpen 
              ? '#02042d' 
              : '#e0c996';

            return (
              <div 
                key={index} 
                className="overflow-hidden transition-all duration-300"
                style={{
                  border: `1px solid ${borderColor}`,
                  backgroundColor: isOpen ? '#e0c996' : 'transparent',
                }}
              >
                <button
                  onClick={() => toggleFaq(index)}
                  className={`w-full text-left flex justify-between items-center p-5 outline-none transition-colors ${
                    !isOpen && (isLight ? 'hover:bg-[#02042d]/5' : 'hover:bg-white/5')
                  }`}
                  style={{
                    fontFamily: 'Uxum Grotesque Regular, sans-serif',
                    color: questionColor,
                    fontSize: 'clamp(16px, 1.5vw, 20px)'
                  }}
                >
                  <span className="pr-4 leading-snug font-medium">{faq.q}</span>
                  <span 
                    className="flex-shrink-0 transition-transform duration-300"
                    style={{ 
                      color: iconColor,
                      transform: isOpen ? 'rotate(45deg)' : 'rotate(0deg)',
                      fontSize: '24px',
                      lineHeight: '1'
                    }}
                  >
                    +
                  </span>
                </button>
                
                <div 
                  className={`transition-all duration-300 ease-in-out ${isOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'}`}
                  style={{ overflow: 'hidden' }}
                >
                  <div 
                    className="px-5 pb-5 pt-0 focus:outline-none"
                    style={{
                      fontFamily: 'Uxum Grotesque Regular, sans-serif',
                      color: answerColor,
                      fontSize: 'clamp(14px, 1.2vw, 16px)',
                      lineHeight: '1.6'
                    }}
                  >
                    {convertPriceText(faq.a)}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
